def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    fg = g != bg

    def isolated(y, x):
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if (dy or dx) and 0 <= y+dy < H and 0 <= x+dx < W and fg[y+dy, x+dx]:
                    return False
        return True

    # find marker line: row or column with most isolated pixels
    best = None
    for y in range(H):
        c = sum(1 for x in range(W) if fg[y, x] and isolated(y, x))
        if best is None or c > best[0]:
            best = (c, 'row', y)
    for x in range(W):
        c = sum(1 for y in range(H) if fg[y, x] and isolated(y, x))
        if c > best[0]:
            best = (c, 'col', x)
    _, kind, idx = best

    if kind == 'row':
        markers = [(x, int(g[idx, x])) for x in range(W) if fg[idx, x]]
    else:
        markers = [(y, int(g[y, idx])) for y in range(H) if fg[y, idx]]
    shape_mask = fg.copy()
    if kind == 'row':
        shape_mask[idx, :] = False
    else:
        shape_mask[:, idx] = False
    cells = list(zip(*np.nonzero(shape_mask)))
    y0, x0, y1, x1 = bbox(cells)
    scol = int(g[cells[0]])
    pat = shape_mask[y0:y1+1, x0:x1+1]

    # along-axis: for row of markers, shapes are laid out along x
    if kind == 'row':
        s0, L = x0, x1 - x0 + 1
    else:
        s0, L = y0, y1 - y0 + 1

    a = [i for i, (p, c) in enumerate(markers) if c == scol][0]
    starts = {a: s0}
    for i in range(a + 1, len(markers)):
        starts[i] = starts[i-1] + L + (markers[i][0] - markers[i-1][0] - 1)
    for i in range(a - 1, -1, -1):
        starts[i] = starts[i+1] - (markers[i+1][0] - markers[i][0] - 1) - L

    out = g.copy()
    order = sorted(starts, key=lambda i: abs(i - a))
    for i in order:
        if i == a:
            continue
        col = markers[i][1]
        s = starts[i]
        ph, pw = pat.shape
        for dy in range(ph):
            for dx in range(pw):
                if pat[dy, dx]:
                    if kind == 'row':
                        yy, xx = y0 + dy, s + dx
                    else:
                        yy, xx = s + dy, x0 + dx
                    if 0 <= yy < H and 0 <= xx < W:
                        out[yy, xx] = col
        emit(out, f"Stamp a copy of the shape in colour {col}, spaced from its neighbour by the same gap as marker {i} from its neighbouring marker.")
    emit(out, "All markers now have their shape copy; final grid.")
    return out
